// intake_dispute row-level security and integrity — generated by `pnpm gen:migration` (02-architecture §4,
// 04-testing §3); SOP-DEL-01 §9 cases added (E2 AC5). Internal only, like intake_decision.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, expect, inject, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  client,
  createDatabase,
  handoverCard,
  inActorTransaction,
  intakeDecision,
  intakeDispute,
  migrateUp,
  site,
  type Database,
  type DbActor,
} from '../index.ts';

const clientA = randomUUID();
const siteA = randomUUID();
const cardA = randomUUID();
const decisionA = randomUUID();
const staff: DbActor = { id: randomUUID(), kind: 'staff', clientIds: [] };
const userOfA: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientA] };
const partnerOfA: DbActor = { id: randomUUID(), kind: 'partner', clientIds: [clientA] };
const disputeOf = (more: Partial<typeof intakeDispute.$inferInsert> = {}) => ({
  id: randomUUID(),
  clientId: clientA,
  decisionId: decisionA,
  reason: 'C3 was in the folder from the start',
  raisedBy: staff.id,
  dueOn: '2026-11-25',
  ...more,
});
let testDb: TestDatabase;
let database: Database;
type Tx = Parameters<Parameters<typeof inActorTransaction>[2]>[0];
const asStaff = <T>(work: (tx: Tx) => Promise<T>) => inActorTransaction(database.db, staff, work);
const countFor = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) => (await tx.select().from(intakeDispute)).length);

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  database = createDatabase(testDb.url);
  await migrateUp(database.pool);
  await asStaff(async (tx) => {
    await tx.insert(client).values({ id: clientA, shortCode: 'CLIENTA', name: 'Client A' });
    await tx.insert(site).values({
      id: siteA,
      clientId: clientA,
      projectId: 'CLIENTA-ES-MAD-001',
      countryCode: 'ES',
      cityCode: 'MAD',
      cityName: 'Madrid',
      runningNo: 1,
      name: 'Site 001',
      standard: 'S',
    });
    await tx.insert(handoverCard).values({
      id: cardA,
      clientId: clientA,
      siteId: siteA,
      version: 1,
      package: 'full',
      status: 'returned',
      submittedAt: new Date(),
      submittedBy: staff.id,
    });
    await tx.insert(intakeDecision).values({
      id: decisionA,
      clientId: clientA,
      cardId: cardA,
      decision: 'returned',
      folderStandard: 'S',
      reasons: 'C3 missing',
      decidedBy: staff.id,
    });
    await tx.insert(intakeDispute).values(disputeOf());
  });
});

afterAll(async () => {
  await database.close();
  await testDb.drop();
});

it('staff see disputes; clients and partners never do (internal, like the decision)', async () => {
  expect([await countFor(staff), await countFor(userOfA), await countFor(partnerOfA)]).toEqual([1, 0, 0]);
});

it('a client cannot write', async () => {
  await expect(
    inActorTransaction(database.db, userOfA, (tx) =>
      tx.insert(intakeDispute).values(disputeOf({ decisionId: randomUUID() })),
    ),
  ).rejects.toThrow();
});

it('one dispute per decision; a blank reason and a half-recorded outcome are refused', async () => {
  await expect(asStaff((tx) => tx.insert(intakeDispute).values(disputeOf()))).rejects.toThrow();
  await expect(
    asStaff((tx) => tx.insert(intakeDispute).values(disputeOf({ id: randomUUID(), reason: ' ' }))),
  ).rejects.toThrow();
  await expect(asStaff((tx) => tx.update(intakeDispute).set({ outcome: 'upheld' }))).rejects.toThrow();
});
